20	/**
21	 * Mount a React component into a specific target element.
22	 */
23	const roots = new Map<string, any>();
24	
25	interface MountOptions {
26	    surfaceLabel?: string;
27	    initialPath?: string;
28	}
29	
30	export function mountModule(moduleName: string, targetId: string, options?: MountOptions) {
31	    const container = document.getElementById(targetId);
32	    if (!container) {
33	        console.error(`⬡ MOUNT_ERROR :: Target element #${targetId} not found`);
34	        return;
35	    }
36	
37	    // ALWAYS unmount before remounting if the container was swapped by main.ts
38	    const existing = roots.get(targetId);
39	    if (existing) {
40	        try {
41	            existing.unmount();
42	        } catch (e) {
43	            // Silence if already unmounted or container detached
44	        }
45	        roots.delete(targetId);
46	    }
47	
48	    const root = createRoot(container);
49	    roots.set(targetId, root);
50	
51	    switch (moduleName) {
52	        case 'NEXUSLINK':
53	            root.render(<NexusLinkLanding surfaceLabel={options?.surfaceLabel || 'NexusLink'} />);
54	            break;
55	        case 'PHYSIS':
56	            root.render(<PhysisVault />);
57	            break;
58	        case 'RESEARCH':
59	            root.render(
60	                <PhysisVault
61	                    initialPath={options?.initialPath || '01_PROJECTS'}
62	                    surfaceLabel={options?.surfaceLabel || 'Research'}
63	                />
64	            );
65	            break;
66	        case 'BRIDGE':
67	            root.render(<Bridge />);
68	            break;
69	        case 'TELEMETRY':
70	            root.render(<TelemetryDeck />);
71	            break;
72	        case 'AGENT_MONITOR':
73	            root.render(<AgentMonitor />);
74	            break;
75	        case 'SEARCH':
76	            root.render(<AlbedoSearch />);
77	            break;
78	        case 'CHRONOS':
79	            root.render(<ChronosStream />);
80	            break;
81	        case 'INDRA':
82	            root.render(<IndraSwarm />);
83	            break;
84	        case 'LOGOS':
85	            root.render(<LogosProjects />);
86	            break;
87	        case 'TICKETS':
88	            root.render(<TicketBoard />);
89	            break;
90	        case 'ORACLE':
91	            root.render(<OraclePage />);
92	            break;
93	        case 'NEURAL_FORGE':
94	            root.render(<NeuralForge />);
95	            break;
96	        case 'MNEMOSYNE':
97	            root.render(<MnemosyneMedia />);
98	            break;
99	        case 'CONCLAVE_MONITOR':
100	            root.render(<ConclaveMonitor />);
101	            break;
102	        case 'CATALOG':
103	            root.render(<DiscoveryCatalog />);
104	            break;
105	        case 'VAULT_DEBUGGER':
106	            root.render(<VaultLinkDebugger />);
107	            break;
108	        default:
109	            console.warn(`⬡ MOUNT_WARN :: No React component for ${moduleName}`);
110	    }
111	}
