113	export function unmountModule(targetId: string) {
114	    const existing = roots.get(targetId);
115	    if (!existing) return;
116	
117	    try {
118	        existing.unmount();
119	    } catch {
120	        // Best effort only. Detached containers are already gone.
121	    } finally {
122	        roots.delete(targetId);
123	    }
124	}
