158	function installRouteAliases() {
159	    const engine = (window as any).nudimmudEngine;
160	    if (!engine || (engine as any).__routeAliasesPatched) return false;
161	
162	    const originalGo = engine.go.bind(engine);
163	    let activeCustomRoute: 'NEXUSLINK' | 'RESEARCH' | null = null;
164	
165	    engine.go = (moduleName: string, query?: string) => {
166	        if (moduleName === 'NEXUSLINK' || moduleName === 'RESEARCH') {
167	            activeCustomRoute = moduleName;
168	            mountCustomRoute(engine, moduleName);
169	            return;
170	        }
171	
172	        if (activeCustomRoute) {
173	            unmountModule(CUSTOM_ROUTE_TARGET_ID);
174	            activeCustomRoute = null;
175	        }
176	
177	        return originalGo(moduleName, query);
178	    };
179	
180	    (engine as any).__routeAliasesPatched = true;
181	    return true;
182	}
183	
184	(function bootstrapRouteAliases() {
185	    if (installRouteAliases()) return;
186	
187	    const interval = window.setInterval(() => {
188	        if (installRouteAliases()) {
189	            window.clearInterval(interval);
190	        }
191	    }, 50);
192	})();
193	
194	// Attach to window for global access from main.ts
195	(window as any).mountModule = mountModule;
