126	function deriveOracleTelemetry(response: any = {}) {
127	    const telemetry = response?.telemetry || {};
128	    const risk = String(telemetry.risk || response?.decision?.risk || response?.risk || 'medium').toUpperCase();
129	    const runtime = String(telemetry.runtime || response?.runtime || response?.decision?.preferredRuntime || 'local').toUpperCase();
130	    const heartbeat = String(
131	        telemetry.heartbeat
132	        || (response?.status === 'FORGE_DEGRADED'
133	            ? 'DEGRADED'
134	            : response?.status === 'CONCLAVE_TIMEOUT'
135	                ? 'DELAYED'
136	                : 'NOMINAL')
137	    ).toUpperCase();
138	    const escalated = Boolean(telemetry.escalated ?? response?.escalated);
139	    const disagreement = Boolean(telemetry.disagreement) || escalated || risk === 'HIGH' || response?.status === 'FORGE_DEGRADED';
140	    const confidenceBand = String(
141	        telemetry.confidenceBand
142	        || (response?.status === 'FORGE_DEGRADED'
143	            ? 'LOW'
144	            : escalated
145	                ? 'GUARDED'
146	                : risk === 'HIGH'
147	                    ? 'LOW'
148	                    : risk === 'MEDIUM'
149	                        ? 'MEDIUM'
150	                        : 'HIGH')
151	    ).toUpperCase();
152	
153	    return {
154	        risk,
155	        runtime,
156	        heartbeat,
157	        escalated,
158	        disagreement,
159	        confidenceBand,
160	        loopCount: Number(telemetry.loopCount || response?.loopCount || 1)
161	    };
