112	    phaseTimer = null;
113	    staleSoftTimer = null;
114	    staleHardTimer = null;
115	    tickInterval = null;
116	}
117	
118	function isActivePhase(phase: OracleCommandPhase) {
119	    return phase === 'submitted' || phase === 'deliberating' || phase === 'stale';
120	}
121	
122	function getElapsedMs(submittedAt: number | null, fallback = 0) {
123	    return submittedAt ? Math.max(0, Date.now() - submittedAt) : fallback;
124	}
125	
126	function startElapsedClock(requestId: string) {
127	    clearIntervalSafe(tickInterval);
128	    tickInterval = globalThis.setInterval(() => {
129	        setState((current) => {
130	            if (current.requestId !== requestId || !current.submittedAt || !isActivePhase(current.phase)) {
131	                clearIntervalSafe(tickInterval);
132	                tickInterval = null;
133	                return current;
134	            }
135	            return {
136	                ...current,
137	                elapsedMs: getElapsedMs(current.submittedAt, current.elapsedMs)
138	            };
139	        });
140	    }, 250);
141	}
142	
143	function schedulePhaseTimers(requestId: string) {
144	    phaseTimer = globalThis.setTimeout(() => {
145	        setState((current) => {
146	            if (current.requestId !== requestId || current.phase !== 'submitted') {
147	                return current;
148	            }
149	            return {
150	                ...current,
151	                phase: 'deliberating',
152	                elapsedMs: getElapsedMs(current.submittedAt, current.elapsedMs)
153	            };
154	        });
155	    }, ORACLE_COMMAND_BUDGETS_MS.deliberationDelay);
156	
157	    staleSoftTimer = globalThis.setTimeout(() => {
158	        setState((current) => {
159	            if (current.requestId !== requestId || !isActivePhase(current.phase)) {
160	                return current;
161	            }
162	            return {
163	                ...current,
164	                phase: 'stale',
165	                staleLevel: 'soft',
166	                elapsedMs: getElapsedMs(current.submittedAt, current.elapsedMs)
167	            };
168	        });
169	    }, ORACLE_COMMAND_BUDGETS_MS.staleSoft);
170	
171	    staleHardTimer = globalThis.setTimeout(() => {
172	        setState((current) => {
173	            if (current.requestId !== requestId || !isActivePhase(current.phase)) {
174	                return current;
175	            }
176	            return {
177	                ...current,
178	                phase: 'stale',
179	                staleLevel: 'hard',
180	                elapsedMs: getElapsedMs(current.submittedAt, current.elapsedMs)
181	            };
182	        });
183	    }, ORACLE_COMMAND_BUDGETS_MS.staleHard);
184	}
185	
186	function hardTimeoutForMode(mode: OracleCommandMode) {
187	    return mode === 'council'
188	        ? ORACLE_COMMAND_BUDGETS_MS.councilHardTimeout
189	        : ORACLE_COMMAND_BUDGETS_MS.directHardTimeout;
190	}
191	
192	function makeRequestId() {
193	    requestCounter += 1;
194	    return `oracle_${Date.now()}_${requestCounter}`;
195	}
196	
197	function normalizeError(error: unknown) {
198	    if (error instanceof Error) {
199	        return error.message || 'ORACLE_COMMAND_FAILED';
200	    }
201	    if (typeof error === 'string' && error.trim()) {
202	        return error.trim();
203	    }
204	    return 'ORACLE_COMMAND_FAILED';
205	}
206	
207	function settleRequest(requestId: string, phase: 'completed' | 'failed', patch: Partial<OracleCommandState>) {
208	    stopTimers();
209	    setState((current) => {
210	        if (current.requestId !== requestId) return current;
211	        const settledAt = Date.now();
212	        return {
213	            ...current,
214	            ...patch,
215	            phase,
216	            settledAt,
217	            elapsedMs: getElapsedMs(current.submittedAt, current.elapsedMs)
218	        };
219	    });
220	}
221	
222	export function getOracleCommandState() {
223	    return cloneState(state);
224	}
225	
226	export function subscribeOracleCommandState(listener: OracleCommandListener) {
227	    listeners.add(listener);
228	    listener(getOracleCommandState());
229	    return () => {
230	        listeners.delete(listener);
231	    };
232	}
233	
234	export function resetOracleCommandState() {
235	    stopTimers();
236	    activeController?.abort();
237	    activeController = null;
238	    setState(createIdleState());
239	}
240	
241	export type OracleStreamCallback = (chunk: { type: 'token' | 'done' | 'error'; token?: string; content?: string; error?: string }) => void;
242	
243	export async function submitOracleCommandStream(
244	    options: OracleSubmitOptions & { onChunk: OracleStreamCallback; modelId?: string }
245	) {
246	    const command = options.command.trim();
247	    if (!command) throw new Error('ORACLE_COMMAND_REQUIRED');
248	
249	    stopTimers();
250	    activeController?.abort();
251	    const requestId = makeRequestId();
252	    const submittedAt = Date.now();
253	    const controller = new AbortController();
254	    activeController = controller;
255	
256	    setState({
257	        requestId,
258	        source: options.source || 'voice',
259	        mode: 'direct',
260	        phase: 'submitted',
261	        staleLevel: null,
262	        command,
263	        response: null,
264	        error: null,
265	        submittedAt,
266	        settledAt: null,
267	        elapsedMs: 0
268	    });
269	
270	    startElapsedClock(requestId);
271	    schedulePhaseTimers(requestId);
272	
273	    const model = options.modelId || 'qwen-liberated:latest';
274	    const url = `/api/oracle/stream?command=${encodeURIComponent(command)}&model=${encodeURIComponent(model)}`;
275	    const es = new EventSource(url);
276	    let full = '';
277	
278	    es.addEventListener('token', (e: MessageEvent) => {
279	        try {
280	            const { token } = JSON.parse(e.data);
281	            full += token;
282	            options.onChunk({ type: 'token', token });
283	        } catch (_) {}
284	    });
285	
286	    es.addEventListener('done', (e: MessageEvent) => {
287	        es.close();
288	        try { const { content } = JSON.parse(e.data); full = content || full; } catch (_) {}
289	        options.onChunk({ type: 'done', content: full });
290	        settleRequest(requestId, 'completed', { response: { content: full }, error: null });
291	    });
292	
293	    es.addEventListener('error', (e: MessageEvent) => {
294	        es.close();
295	        let msg = 'STREAM_FAILED';
296	        try { msg = JSON.parse((e as any).data)?.message || msg; } catch (_) {}
297	        options.onChunk({ type: 'error', error: msg });
298	        settleRequest(requestId, 'failed', { response: null, error: msg });
299	    });
300	
301	    es.onerror = () => {
302	        es.close();
303	        settleRequest(requestId, 'failed', { response: null, error: 'SSE_CONNECTION_LOST' });
304	    };
305	}
306	
307	export async function submitOracleCommand(options: OracleSubmitOptions) {
308	    const command = options.command.trim();
309	    if (!command) {
310	        throw new Error('ORACLE_COMMAND_REQUIRED');
311	    }
312	
313	    stopTimers();
314	    activeController?.abort();
315	
316	    const requestId = makeRequestId();
317	    const submittedAt = Date.now();
318	    const mode: OracleCommandMode = options.useCouncil ? 'council' : 'direct';
319	    const controller = new AbortController();
320	    const upstreamSignal = options.signal;
321	    const relayAbort = () => controller.abort();
322	
323	    if (upstreamSignal) {
324	        if (upstreamSignal.aborted) {
325	            controller.abort();
326	        } else {
327	            upstreamSignal.addEventListener('abort', relayAbort, { once: true });
328	        }
329	    }
330	
331	    activeController = controller;
332	
333	    setState({
334	        requestId,
335	        source: options.source || 'typed',
336	        mode,
337	        phase: 'submitted',
338	        staleLevel: null,
339	        command,
340	        response: null,
341	        error: null,
342	        submittedAt,
343	        settledAt: null,
344	        elapsedMs: 0
345	    });
346	
347	    startElapsedClock(requestId);
348	    schedulePhaseTimers(requestId);
349	
350	    try {
351	        const response = await apiFetchWithTimeout(ORACLE_COMMAND_ENDPOINT, hardTimeoutForMode(mode), {
352	            method: 'POST',
353	            headers: { 'Content-Type': 'application/json' },
354	            body: JSON.stringify({
355	                command,
356	                useCouncil: mode === 'council',
357	                modelId: mode === 'direct' ? options.modelId || undefined : undefined
358	            }),
359	            signal: controller.signal
360	        });
361	
362	        const payload = await response.json().catch(() => ({} as OracleCommandResponse));
363	        if (!response.ok) {
364	            const message = String(
365	                (payload as Record<string, unknown>)?.message
366	                || (payload as Record<string, unknown>)?.error
367	                || `HTTP_${response.status}`
368	            );
369	            throw new Error(message);
370	        }
371	
372	        settleRequest(requestId, 'completed', {
373	            response: payload,
374	            error: null
375	        });
376	        return payload;
377	    } catch (error) {
378	        if (state.requestId === requestId) {
379	            settleRequest(requestId, 'failed', {
380	                response: null,
381	                error: normalizeError(error)
382	            });
383	        }
384	        throw error;
385	    } finally {
386	        if (upstreamSignal) {
387	            upstreamSignal.removeEventListener('abort', relayAbort);
388	        }
389	        if (activeController === controller) {
390	            activeController = null;
391	        }
392	    }
393	}
